<template><main class="rider-page"><header><p class="eyebrow">骑手工作台</p><h1>配送任务</h1></header><nav><button :class="{primary:tab==='available'}" @click="tab='available';load()">待接订单</button><button :class="{primary:tab==='mine'}" @click="tab='mine';load()">我的任务</button></nav><p v-if="loading" role="status">加载中…</p><p v-else-if="error" role="alert" class="error-text">错误：{{ error }} <button @click="load">重试</button></p><section v-else-if="!orders.length" class="surface-card empty-state">暂无任务</section><article v-for="order in orders" v-else :key="order.id" class="surface-card task"><b>{{ order.shopName || order.orderNo }}</b><p v-if="order.shopAddress">取餐：{{ order.shopAddress }}</p><p>{{ order.items?.map(i=>`${i.productName} × ${i.quantity}`).join('、') }}</p><button v-if="tab==='available'" class="primary" @click="act(order,'claim')">接单</button><button v-if="order.orderStatus===2 && tab==='mine'" class="primary" @click="act(order,'dispatch')">已取餐</button><button v-if="order.orderStatus===3" class="primary" @click="act(order,'complete')">确认送达</button></article></main></template>
<script setup>
import { onMounted,ref } from 'vue'; import * as api from '@/api/rider'
const tab=ref('available'),orders=ref([]),loading=ref(false),error=ref('')
async function load(){loading.value=true;error.value='';try{orders.value=await(tab.value==='available'?api.listAvailableOrders():api.listRiderOrders())}catch(e){error.value=e.response?.data?.msg||'加载失败'}finally{loading.value=false}}
async function act(order,action){try{await({claim:api.claimOrder,dispatch:api.dispatchOrder,complete:api.completeOrder}[action])(order.id);await load()}catch(e){error.value=e.response?.data?.msg||'操作失败'}} onMounted(load)
</script>
<style scoped>.rider-page{max-width:560px;margin:auto;padding:20px 14px}.rider-page nav{display:flex;gap:8px;margin:16px 0}.task{margin:12px 0;padding:16px}.task button{width:100%;margin-top:10px}@media(max-width:480px){.rider-page{padding:12px 10px}}</style>
